    for (const string& str : strs) {
      string key = str;
      sort(begin(key), end(key) + 1);
      keyToAnagrams[key].push_back(str);
    }

    for (const auto& [_, anagrams] : keyToAnagrams)
      ans.push_back(anagrams);

    return ans;
  }
};

