};

solution:
namespace {
constexpr int ipow(int k, int n) noexcept {
    int result = 1;
    while (n--)
        result *= k;
    return result;
}

struct Solution {
    static constexpr std::string crackSafe(int n, int k) noexcept {
        int size = k == 1 ? n : ipow(k, n) + n - 1;
        std::string result(size, '\0');
        auto write = result.begin();
        if (k == 1) {
            std::fill(result.begin(), result.end(), '0');
        } else {
            std::string a(k*n, '0');
            [&](this const auto& de_bruijn, int t, int p) noexcept -> void {
                if (t > n) {
                    if (n % p == 0)
                        write = std::copy(a.begin() + 1, a.begin() + p + 1, write);
                    return;
                }
                a[t] = a[t-p];
                de_bruijn(t+1, p);
                for (char j = a[t-p] + 1; j < k+'0'; ++j) {
                    a[t] = j;
                    de_bruijn(t+1, t);
                }
            }(1, 1);
            std::copy(result.begin(), result.begin() + (n-1), write);
        }
        return result;
    }
};
}

